import { tags } from "typia";

/**
 * Single node within the hierarchical shoppingMall category tree.
 *
 * This type represents a denormalized view combining core category fields from
 * `shopping_mall_categories` with hierarchical composition through the
 * `children` property.
 *
 * Each node can be used to render navigation elements, breadcrumbs, and
 * selectors without additional queries, and the full tree is obtained via the
 * `IShoppingMallCategoryTree` root type.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallCategoryTreeNode = {
  /**
   * Identifier of the category represented by this node.
   *
   * This matches the `id` column of the underlying `shopping_mall_categories`
   * record and uniquely identifies the node in the tree.
   *
   * Clients should use this value when triggering category-specific actions
   * such as filtering products or navigating to a category page.
   */
  id: string & tags.Format<"uuid">;

  /**
   * URL-friendly slug for the category represented by this node.
   *
   * This slug mirrors the `slug` column in `shopping_mall_categories` and is
   * suitable for constructing readable URLs, deep links, and SEO-friendly
   * paths.
   *
   * In combination with ancestor slugs, it can form hierarchical URL
   * structures for category pages.
   */
  slug: string;

  /**
   * English display name of the category for this node.
   *
   * This corresponds to the `name_en` column and serves as the default label
   * when localization is not applied.
   *
   * Front-end clients may still choose to override this with localized labels
   * from `shopping_mall_category_localizations`, but including it here allows
   * basic rendering with a single API call.
   */
  name_en: string;

  /**
   * Lifecycle status of the category at this node.
   *
   * The value is copied from the `status` column of the underlying
   * `shopping_mall_categories` record and is used by callers to decide
   * whether to render or dim this node in navigation components.
   *
   * Typical values include operational states such as `active`, `hidden`, or
   * `deprecated`, and the backend constructs the tree so that only
   * appropriately visible nodes are included for public usage.
   */
  status: string;

  /**
   * Ordering hint for this node relative to its siblings at the same depth.
   *
   * This numeric value is derived from the `sort_order` column and is used to
   * sort siblings when rendering.
   *
   * Lower numbers typically appear earlier in menus and lists, providing
   * fine-grained control over category presentation.
   */
  sort_order: number & tags.Type<"int32">;

  /**
   * Indicates whether this node is currently considered a leaf within the
   * tree.
   *
   * This value mirrors the `is_leaf` column from `shopping_mall_categories`
   * and allows clients to determine if further expansion is possible.
   *
   * Leaf nodes usually represent categories that directly accept product
   * assignments, whereas non-leaf nodes primarily organize subtrees.
   */
  is_leaf: boolean;

  /**
   * List of direct child category nodes under this node.
   *
   * Each element is another `IShoppingMallCategoryTreeNode`, enabling
   * recursive traversal of the full hierarchy down to leaves.
   *
   * The server constructs this list by combining `shopping_mall_categories`
   * with hierarchical information (for example from
   * `shopping_mall_category_closures`), ensuring that children are ordered
   * according to `sort_order`.
   */
  children: IShoppingMallCategoryTreeNode[];
};
